 // تُملأ فقط بأسئلة موثقة من صفحات الكتاب السوري للصف التاسع.
function allGrammar(){return level()==="تاسع"?ninthBookExercises:grammarMode==="exam"?[...examLessons,...examSkills,...secondSession,...session2022,...session2022second,...examRhetoric,...examComprehension].filter(q=>(examSession==="all"||((q.source||"").includes("الدورة "+examSession)))&&(examCategory==="all"||examType(q)===examCategory)) :(level().includes("علمي")?[...bacBookReading]:[])}

function questionLesson(q){
 if(!q.bookPage)return 'أسئلة الدورات';
 const match=(q.title||'').match(/—\s*([^—]+?)\s*—/);
 return match?match[1].trim():'أسئلة من الكتاب';
}
function allowedGrammar(){
 const all=allGrammar(),select=$('arabicLessonFilter'),filter=select?select.value:'all';
 return filter==='all'?all:all.filter(q=>questionLesson(q)===filter);
}
function updateLessonFilter(){
 const select=$('arabicLessonFilter');if(!select)return;
 const all=allGrammar(),lessons=[...new Set(all.map(questionLesson))];
 const previous=select.value;
 select.innerHTML='<option value="all">كل الدروس</option>'+lessons.map(v=>'<option value="'+escape(v)+'">'+escape(v)+'</option>').join('');
 select.value=lessons.includes(previous)?previous:'all';
 $('arabicLessonCount').textContent=all.length+' سؤالاً متاحاً';
}
function examType(q){const t=q.title+" "+q.word;if(/التشبيه|صورة بيانية|التشخيص|محسن بديعي/.test(t))return "بلاغة";if(/المفعول المطلق|المفعول لأجله|المفعول فيه|الحال|أعرب|إعراب|ظرف/.test(t))return "إعراب";if(/أحوّل|أحول|أجعل|أضع كلمة|تحويل/.test(t))return "تحويل";if(/أذكر|أوضح|أوضّح|أستنتج|أبين|أبيّن|الفكرة|المقطع|النص الوصفي|الخط العربي|ملحمة ميسلون|اليوم الأغر|الناعورة|روائع الآثار/.test(t))return "فهم النص";if(/إعراب|المنادى|المبتدأ|المضاف إليه|الفعل المجزوم|الفعل الماضي|فاعل|مفعول به|خبر كأن|ظرف المكان|بناء الماضي|صلة الموصول/.test(t))return "إعراب";if(/تحويل|توكيد/.test(t))return "تحويل";if(/تشبيه|صورة بيانية/.test(t))return "بلاغة";if(/أثر العلم|الدعوة إلى المدارس|الارتباط بالوطن|قيمة إنسانية/.test(t))return "فهم النص";return "صرف وإملاء"}

function normalizeArabic(t){return String(t||"").normalize("NFKC").replace(/[\u064B-\u065F\u0670\u0640]/g,"").replace(/[أإآ]/g,"ا").replace(/ى/g,"ي").replace(/ة/g,"ه").replace(/\s+/g," ").trim()}
function partialReview(q,input){
 const a=normalizeArabic(input);
 if(!a)return {message:"اكتب إجابتك أولاً.",score:null};
 const key=normalizeArabic(q.word);
 const isFirst=(q.source||"").includes("الأولى 2020");
 const rubric=isFirst?({
 "شوكه":[["الوظيفة: فاعل",5,["فاعل"]],["الحالة: مرفوع",2,["مرفوع"]],["العلامة: الضمة",2,["ضمه"]]],
 "تبلغ":[["نوع الفعل: مضارع",5,["مضارع"]],["الحالة: مجزوم",2,["مجزوم"]],["العلامة: السكون",2,["سكون"]]],
 "مداوله":[["الوظيفة: مبتدأ",5,["مبتدا"]],["الحالة: مرفوع",2,["مرفوع"]],["العلامة: الضمة",2,["ضمه"]]],
 "الاوطان":[["الوظيفة: مضاف إليه",5,["مضاف اليه"]],["الحالة: مجرور",2,["مجرور"]],["العلامة: الكسرة",2,["كسره"]]]
 })[key]:null;
 const expected=normalizeArabic(q.answer);
 const checks=rubric||(
 /فاعل|مبتدا|مضاف اليه|منادي|فعل مضارع|فعل ماض|جمله/.test(expected)
 ?[["الوظيفة النحوية",null,["فاعل","مبتدا","مضاف اليه","منادي","فعل مضارع","فعل ماض","جواب شرط","صفه"].filter(x=>expected.includes(x))],["الحالة أو المحل",null,["مرفوع","منصوب","مجرور","مجزوم","مبني","لا محل","في محل نصب"].filter(x=>expected.includes(x))],["العلامة",null,["ضمه","فتحه","كسره","سكون"].filter(x=>expected.includes(x))]].filter(x=>x[2].length)
 :null);
 if(!checks||checks.length<2)return {message:"لا يوجد سلم عناصر موثوق لهذا السؤال بعد. قارن إجابتك بالحل المرجعي؛ لا تُحتسب درجة آلية.",score:null};
 const parts=checks.map(([name,weight,terms])=>({name,weight,ok:terms.some(t=>a.includes(t))}));
 const total=parts.reduce((n,p)=>n+(p.weight||0),0),hits=parts.reduce((n,p)=>n+(p.ok?(p.weight||0):0),0);
 const detail=parts.map(p=>(p.ok?"✓ ":"○ ")+p.name+(p.weight!==null?" ("+p.weight+" درجات)":"")).join("\n");
 return {score:null,message:(total?"مطابقة نصية إرشادية لعناصر سلم الدورة: "+hits+" من "+total+" درجة محتملة.":"مراجعة أولية للعناصر دون درجات:")+"\n"+detail+"\nهذه ليست علامة مصحَّحة: قد تكون الإجابة صحيحة بصياغة أخرى، وقد تظهر كلمات صحيحة في سياق خاطئ. راجع الحل المرجعي أو اطلب مراجعة المعلم."};
}

