const supplementaryContexts={"ما مصدر «استيقظ»؟":"استيقظَ الطالبُ مبكراً استعداداً للمدرسة.","ما نوع المشتق «محفوفة»؟":"كانتِ الحديقةُ محفوفةً بالأشجارِ.","لماذا كُتبت الألف مقصورة في «المُلتقى»؟":"كانَ المُلتقى الثقافيُّ مفيداً.","ما الإعلال في «غفتْ»؟":"غفتْ الطفلةُ بهدوءٍ.","لماذا كتبت الألف مقصورة في «درى»؟":"درى الطالبُ حقيقةَ الأمرِ.","ما مصدر «أرّقَ»؟":"أرّقَ الضجيجُ المسافرَ.","ما اسم الفاعل من «عكف»؟":"عكفَ الباحثُ على دراسةِ الموضوعِ.","أكّد لفظ «البحرِ» توكيداً لفظياً.":"يتغنّى الشعراءُ بجمالِ البحرِ.","علّل اختلاف علامة الإعراب بين «أبي» و«أبيه».":"جاءَ أبي، ومررتُ بأبيهِ."};
function questionPrompt(q){
 const w=q.word||"",title=q.title||"";if(q.bookPage)return w;
 if(/^(ما |لماذا|رتّب|حوّل|أكّد|علّل|كيف |إلى ماذا|اذكر|استخلص|هات |تغنّى)/.test(w))return w;
 if(/جملة «/.test(w))return "بيّن المحل الإعرابي لـ"+w+" في السياق المعروض.";
 if(/اسم فاعل|مصدر|الألف|إعلال|مشتق|معجم/.test(title))return "أجب عن السؤال الصرفي أو الإملائي: «"+w+"»";
 if(/تشبيه|بلاغة/.test(title))return "حلّل الصورة البيانية: «"+w+"»";
 return "أعرب الكلمة الآتية في الجملة المعروضة: «"+w+"»";
}
