function bookBrowse(page){const dir=bookDirectory(),total=bookCounts[dir];$('arabicNinthQuickPages').hidden=dir!=='9-Arabic';const n=Math.max(1,Math.min(total,Math.round(Number(page)||1)));$('arabicBookPageNumber').max=total;$('arabicBookPageNumber').value=n;$('arabicBookTotal').textContent='من '+total;$('arabicBookPrev').disabled=n===1;$('arabicBookNext').disabled=n===total;$('arabicBookPreview').src='book-pages/'+dir+'/'+String(n).padStart(3,'0')+'.webp';}
